    // upper-triangular output; skip them completely.
    if (tile_row > tile_col) return;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    // Each thread computes a TTxTT (2x2) register-blocked sub-tile of C
    int ry0 = ty * TT;
    int ry1 = ry0 + 1;
    int cx0 = tx * TT;
    int cx1 = cx0 + 1;
    int row0 = tile_row * TILE + ry0;
    int row1 = tile_row * TILE + ry1;
    int col0 = tile_col * TILE + cx0;
    int col1 = tile_col * TILE + cx1;
    __shared__ float As_data[TILE * TILE];
    __shared__ float Bs_data[TILE * TILE];
    Tensor As = make_tensor(make_smem_ptr(As_data),
                             make_shape(Int<TILE>{}, Int<TILE>{}),
                             make_stride(Int<TILE>{}, Int<1>{}));
    Tensor Bs = make_tensor(make_smem_ptr(Bs_data),
                             make_shape(Int<TILE>{}, Int<TILE>{}),
                             make_stride(Int<TILE>{}, Int<1>{}));
    Tensor gA = make_tensor(make_gmem_ptr(A_ptr), make_shape(N, N), make_stride(N, Int<1>{}));
    Tensor gB = make_tensor(make_gmem_ptr(B_ptr), make_shape(N, N), make_stride(N, Int<1>{}));
    Tensor gC = make_tensor(make_gmem_ptr(C_ptr), make_shape(N, N), make_stride(N, Int<1>{}));
    float acc00 = 0.f, acc01 = 0.f, acc10 = 0.f, acc11 = 0.f;
    // A is upper triangular => A(row, k) == 0 for k < row
    // B is upper triangular => B(k, col) == 0 for k > col
    // So only k-tiles in [tile_row, tile_col] can contribute.
    for (int kt = tile_row; kt <= tile_col; ++kt) {
        int a_col0 = kt * TILE + cx0;
        int a_col1 = kt * TILE + cx1;
        // Vectorized (float2) loads of contiguous column pairs when fully in-bounds
        if (row0 < N) {
            if (a_col1 < N) {
                float2 av = *reinterpret_cast<const float2*>(A_ptr + row0 * N + a_col0);
                As(ry0, cx0) = av.x;
                As(ry0, cx1) = av.y;
            } else {
                As(ry0, cx0) = (a_col0 < N) ? A_ptr[row0 * N + a_col0] : 0.f;
                As(ry0, cx1) = 0.f;
            }
        } else {
            As(ry0, cx0) = 0.f;
            As(ry0, cx1) = 0.f;
        }
        if (row1 < N) {
            if (a_col1 < N) {
                float2 av = *reinterpret_cast<const float2*>(A_ptr + row1 * N + a_col0);
                As(ry1, cx0) = av.x;
                As(ry1, cx1) = av.y;
            } else {
                As(ry1, cx0) = (a_col0 < N) ? A_ptr[row1 * N + a_col0] : 0.f;
                As(ry1, cx1) = 0.f;
            }
        } else {
            As(ry1, cx0) = 0.f;
            As(ry1, cx1) = 0.f;
        }
        int b_row0 = kt * TILE + ry0;
        int b_row1 = kt * TILE + ry1;
        if (b_row0 < N) {
            if (col1 < N) {
                float2 bv = *reinterpret_cast<const float2*>(B_ptr + b_row0 * N + col0);
                Bs(ry0, cx0) = bv.x;
                Bs(ry0, cx1) = bv.y;
            } else {
                Bs(ry0, cx0) = (col0 < N) ? B_ptr[b_row0 * N + col0] : 0.f;
                Bs(ry0, cx1) = 0.f;
            }
        } else {
            Bs(ry0, cx0) = 0.f;
            Bs(ry0, cx1) = 0.f;
        }
        if (b_row1 < N) {
            if (col1 < N) {
                float2 bv = *reinterpret_cast<const float2*>(B_ptr + b_row1 * N + col0);
                Bs(ry1, cx0) = bv.x;
                Bs(ry1, cx1) = bv.y;
            } else {
                Bs(ry1, cx0) = (col0 < N) ? B_ptr[b_row1 * N + col0] : 0.f;
                Bs(ry1, cx1) = 0.f;
            }
        } else {
            Bs(ry1, cx0) = 0.f;
            Bs(ry1, cx1) = 0.f;
        }
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float as0 = As(ry0, k);
            float as1 = As(ry1, k);
            float bs0 = Bs(k, cx0);
            float bs1 = Bs(k, cx1);
            acc00 += as0 * bs0;
            acc01 += as0 * bs1;
            acc10 += as1 * bs0;
            acc11 += as1 * bs1;
        }
        __syncthreads();
    }
    if (row0 < N && col0 < N && row0 <= col0) gC(row0, col0) = acc00;
    if (row0 < N && col1 < N && row0 <= col1) gC(row0, col1) = acc01;
    if (row1 < N && col0 < N && row1 <= col0) gC(row1, col0) = acc10;
    if (row1 < N && col1 < N && row1 <= col1) gC(row1, col1) = acc11;
}

torch::Tensor cute_triu_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");

    int N = (int)A.size(0);
    TORCH_CHECK((int)A.size(1) == N, "A must be square");
    TORCH_CHECK((int)B.size(0) == N && (int)B.size(1) == N, "B must be square and match A");

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    // Zero-init since blocks fully below the diagonal, and the
    // lower-triangular part of diagonal blocks, are never written.
    auto C = torch::zeros({N, N}, A.options());

    int num_tiles = (N + TILE - 1) / TILE;
    dim3 block(TILE / TT, TILE / TT);
    dim3 grid(num_tiles, num_tiles);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    triu_matmul_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), N);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE triu_matmul launch failed");
    return C;
}
